    def __post_init__(self) -> None:
        for field in ("plan_id", "capability", "scope_id"):
            object.__setattr__(self, field, _text(getattr(self, field), field))
        if (
            self.version <= 0
            or self.interval <= timedelta(0)
            or self.release_window_interval <= timedelta(0)
